	[41716] = {
		id = 41716,
		changeUnitTrigger = true,
		describe = '#L10#液态金属：#L0#每次受击时会将20%的受击伤害吸收转化为等量生命值，并提升自身20%抵御率和抵御强度1回合，每当成功触发抵御时会触发一次【硬化反击】效果（永久提升自身10%基础物防（可叠加10次）并对攻击者进行一次反击，伤害为300%物防的真实伤害）\n#F10# \n#F40##L10#奋不顾身：#L0#己方忍者受到超过其80%当前生命的主动攻击伤害时，美录梅塔会代替承担此次攻击中的伤害；美录梅塔自身受到致命攻击时，则免疫此次致命攻击的伤害，触发以上任一效果后奋不顾身将进入2回合冷却\n#F10# \n#F40##L10#生锈：#L0#美录梅塔死亡时，会生锈解体成美录坦，美录坦继承美录梅塔#C0x01a001#$(30+skillLevel*0.3-0.3)$%#C0x5B545B#的全初始属性（刷新被动并重置小技能冷却）',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
