	[60032416] = {
		id = 60032416,
		changeUnitTrigger = true,
		describe = '#L10#Huyết Nguyệt Mai Táng: #L0#Miễn dịch [Đóng Băng Tâm Trí], khi hàng trước phe ta hoặc bản thân tử vong sẽ để lại một phân thân, phân thân băng kế thừa 30% HP tối đa của Itachi (kích hoạt tối đa 2 lần), khi bị phá hủy sẽ gây sát thương lên toàn bộ địch bằng 240% công đặc biệt cơ bản và 100% đóng băng ngẫu nhiên 1 kẻ địch trong 2 hiệp\n#F10# \n#F40##L10#Ánh Sáng Tối Thượng: #L0#Khi bắt đầu chiến đấu, bản thân tăng số tầng Ánh Sáng Tối Thượng theo số lượng địch (địch 1/3/5 tương ứng 1/2/3 tầng, tối đa 3 tầng; khi mất HP một lần vượt 20% HP tối đa sẽ tiêu hao 1 tầng, khiến lượng HP mất lần này = 20% HP tối đa, đồng thời có xác suất #C0x01a001#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# đóng băng tâm trí nguồn gây sát thương 1 hiệp)\n#F10# \n#F40##L10#Săn Giết Huyết Nguyệt: #L0#Khi bắt đầu chiến đấu đánh dấu ngẫu nhiên 1 kẻ địch hàng sau thành [Săn Giết] trong 2 hiệp (chỉ có thể bị xóa bỏ, giảm 90% tốc độ cơ bản; khi Săn Giết kết thúc hoặc bị xóa sẽ 100% đóng băng tâm trí mục tiêu 1 hiệp, Itachi sẽ ưu tiên tấn công mục tiêu Săn Giết)',
		iconRes = 'battle/skill_icon/skillicon_3241_skill_6.png',
		isCombat = true,
		passiveTriggerType = 7,
		posChoose = 5,
		skillName = 'Chôn huyết nguyệt',
		skillProcess = __data_t__skillProcess[60032416],
		-- {324161, 324162, 324164}
		skillType = 3,
		skillType2 = 3,
		starEffect = __data_t__starEffect[60032416],
		-- {10}
		starEffectDesc = 'Hiệu ứng bổ sung: Khi HP lần đầu thấp hơn 60% và 30% sẽ hồi 20% HP và lần lượt nhận 1 Ánh Sáng Thiên Đường tối đa',
		zawakeEffect = __data_t__zawakeEffect[60032416],
		-- {79004}
		zawakeEffectDesc = '#L10#Tuyết Vùi Lấp: #L0#Miễn dịch đóng băng, khi hàng trước phe ta hoặc bản thân chết sẽ để lại Thân Băng, Thân Băng kế thừa 30% HP tối đa của Kyurem (giới hạn kích hoạt 2 lần), khi bị phá hủy sẽ gây sát thương lên toàn bộ kẻ địch bằng 240% Tấn Công Đặc Biệt cơ bản, và có 100% tỷ lệ đóng băng ngẫu nhiên 1 kẻ địch trong 2 lượt\n#F10# \n#F40##L10#Hoa Tuyết Hộ Vệ: #L0#Khi bắt đầu chiến đấu bản thân nhận thêm Hoa Tuyết theo số lượng kẻ địch (kẻ địch 1/3/5 con tương ứng 1/2/3 Hoa Tuyết, giới hạn 3 Hoa Tuyết; khi mất HP trong 1 lần vượt quá 20% HP tối đa, sẽ tiêu hao 1 Hoa Tuyết, khiến lượng HP mất lần này bằng 20% HP tối đa, mỗi lần dùng Hoa Tuyết sẽ hồi phục 8% HP (không vượt quá 300% Tấn Công Vật Lý) đồng thời có #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# tỷ lệ đóng băng kẻ tấn công, và 30% tỷ lệ đóng băng mục tiêu ngẫu nhiên thêm 1 lượt) Khi kết thúc 3 lượt lớn đầu tiên, bản thân sẽ nhận thêm 1 Hoa Tuyết\n#F10# \n#F40##L10#Truy Sát Đóng Băng: #L0#Khi bắt đầu chiến đấu sẽ đánh dấu ngẫu nhiên 1 kẻ địch ở hàng sau làm mục tiêu [Truy Sát] trong 2 lượt (chỉ có thể bị xóa bỏ, giảm 90% Tốc Độ cơ bản, khi Truy Sát kết thúc hoặc bị xóa bỏ sẽ có 100% tỷ lệ đóng băng mục tiêu 1 lượt, Kyurem sẽ ưu tiên tấn công mục tiêu truy sát trước)',
		zawakeSimpleDesc = '#C0x5c9970#Khi sử dụng Hoa Tuyết sẽ hồi phục 8% HP tối đa của bản thân (không vượt quá 300% Tấn Công Vật Lý), đồng thời có 30% tỷ lệ đóng băng thêm 1 lượt lên mục tiêu địch ngẫu nhiên, khi kết thúc 3 lượt lớn đầu tiên, bản thân sẽ nhận thêm 1 Hoa Tuyết#C0x5B545B#',
		zawakeSimpleType = 1
	},
