	[260026] = {
		id = 260026,
		describe = '#L10#Cửu Vĩ Thiên Xung:#L0#Miễn dịch mọi khống chế; bỏ qua 50% cả hai phòng thủ của mục tiêu\n#F20#\n#F40##L10#Ý Chí Thép:#L0#Khi HP lần đầu xuống dưới 80%, 60%, 40%, 20% sẽ vào【Ý Chí Thép】1 hiệp; trong【Ý Chí Thép】nhận giảm sát thương cuối cùng 30%, khi bị tấn công chắc chắn dùng đánh thường hoặc kỹ năng nhỏ phản kích kẻ địch\n#F20#\n#F40##L10#Thép Chi Lực:#L0#Mỗi 1% HP đã mất tăng 1% bonus sát thương, tối đa 50%; khi bị tấn công có 30% xác suất dùng đánh thường phản kích kẻ địch',
